import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/app/data/inventory.db'
API_KEY = os.environ.get('API_KEY', 'dev-key-12345')
RATE_LIMIT = int(os.environ.get('RATE_LIMIT', '0'))  # 0 = disabled

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, sku TEXT, name TEXT, 
        price REAL, supplier TEXT, internal_cost REAL,
        margin_pct REAL, warehouse_code TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY, key_hash TEXT, 
        owner TEXT, permissions TEXT, created_at TEXT)''')
    db.execute('''INSERT OR IGNORE INTO products VALUES 
        (1, 'WDG-001', 'Widget A', 9.99, 'Acme Corp', 3.20, 68.0, 'WH-EAST'),
        (2, 'WDG-002', 'Widget B', 14.99, 'Acme Corp', 5.10, 66.0, 'WH-WEST'),
        (3, 'GDG-001', 'Gadget X', 29.99, 'TechParts', 12.50, 58.3, 'WH-EAST')''')
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    # API key validation - basic tier
    key = request.headers.get('X-Api-Key', '')
    if key != API_KEY:
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    """Search products by various fields. Supports partial matching."""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')

    # Validate price range inputs
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'invalid price range'}), 400

    # Category filter uses parameterized query
    # Sort field is validated against allowlist... mostly
    allowed_sorts = ['name', 'price', 'sku', 'supplier']

    db = get_db()

    if category:
        # Safe: parameterized
        base_query = "SELECT id, sku, name, price, supplier FROM products WHERE sku LIKE ? AND price BETWEEN ? AND ?"
        params = [f"%{category}%", min_p, max_p]
    else:
        base_query = "SELECT id, sku, name, price, supplier FROM products WHERE price BETWEEN ? AND ?"
        params = [min_p, max_p]

    # ORDER BY injection - sort_by not properly validated when it contains expressions
    if sort_by not in allowed_sorts:
        # "Fallback" that still uses the user input for compound sort expressions
        # Developer thought this regex was sufficient
        import re
        if re.match(r'^[a-zA-Z_,\s]+$', sort_by):
            order_clause = f" ORDER BY {sort_by}"
        else:
            order_clause = " ORDER BY name"
    else:
        order_clause = f" ORDER BY {sort_by}"

    full_query = base_query + order_clause

    try:
        results = db.execute(full_query, params).fetchall()
        return jsonify({'products': [dict(r) for r in results], 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    db = get_db()
    result = db.execute("SELECT id, sku, name, price, supplier FROM products WHERE id = ?", (product_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
